import net.minecraft.world.phys.AABB;
/** Actual manual/CC gantry, genuine column loading, original arm travel and retained carried fuel. */
public final class RbmkCraneEntity extends BlockEntity implements RbmkTargetConsole,ComputerControl,MachineView,MuffledMachine {
    public int centerX,centerY,centerZ,spanF,spanB,spanL,spanR,height,craneRotationOffset;public boolean setUpCrane,muffled;public double lastTiltFront,lastTiltLeft,tiltFront,tiltLeft,lastPosFront,lastPosLeft,posFront,posLeft,syncFront,syncLeft,lastProgress=1,progress=1,syncProgress=1,loadedHeat,loadedEnrichment;private boolean goesDown,hasLoaded;private ItemStack loaded=ItemStack.EMPTY;private static final double SPEED=.05;
    public RbmkCraneEntity(BlockPos pos,BlockState state){super(RbmkCraneContent.ENTITY.get(),pos,state);}
    @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
    public static void tick(Level level,BlockPos pos,BlockState state,RbmkCraneEntity crane){crane.tick(level);}
    private void tick(Level world){if(world.isClientSide){lastTiltFront=tiltFront;lastTiltLeft=tiltLeft;lastPosFront=posFront;lastPosLeft=posLeft;lastProgress=progress;posFront=syncFront;posLeft=syncLeft;progress=syncProgress;}
        if(world instanceof ServerLevel){var column=column();if(column!=null)column.craneIndicator=10;if(goesDown){if(progress>0)progress-=.04;else{progress=0;goesDown=false;if(column instanceof RbmkLoadable loadable&&canTargetInteract(loadable)){if(!loaded.isEmpty()){loadable.load(loaded);loaded=ItemStack.EMPTY;}else{loaded=loadable.provideNext();loadable.unload();}setChanged();}}}else if(progress!=1){progress+=.04;if(progress>1)progress=1;}}
        var dir=DummyableBlock.facing(getBlockState());var side=dir.getClockWise();double minX=worldPosition.getX()+.5-side.getStepX()*1.5,maxX=worldPosition.getX()+.5+side.getStepX()*1.5+dir.getStepX()*2,minZ=worldPosition.getZ()+.5-side.getStepZ()*1.5,maxZ=worldPosition.getZ()+.5+side.getStepZ()*1.5+dir.getStepZ()*2;var players=world.getEntitiesOfClass(Player.class,new AABB(Math.min(minX,maxX),worldPosition.getY(),Math.min(minZ,maxZ),Math.max(minX,maxX),worldPosition.getY()+2,Math.max(minZ,maxZ)));tiltFront=tiltLeft=0;
        if(!players.isEmpty()&&!isCraneLoading()){int bits=RbmkCraneInput.get(players.getFirst());boolean up=(bits&1)!=0,down=(bits&2)!=0,left=(bits&4)!=0,right=(bits&8)!=0;if(up&&!down){tiltFront=30;if(!world.isClientSide)posFront+=SPEED;}if(!up&&down){tiltFront=-30;if(!world.isClientSide)posFront-=SPEED;}if(left&&!right){tiltLeft=30;if(!world.isClientSide)posLeft+=SPEED;}if(!left&&right){tiltLeft=-30;if(!world.isClientSide)posLeft-=SPEED;}if((bits&16)!=0)goesDown=true;}
        posFront=net.minecraft.util.Mth.clamp(posFront,-spanB,spanF);posLeft=net.minecraft.util.Mth.clamp(posLeft,-spanR,spanL);if(world instanceof ServerLevel server){if(loaded.getItem() instanceof RbmkFuelRodItem){loadedHeat=RbmkFuelRodItem.getHullHeat(loaded);loadedEnrichment=RbmkFuelRodItem.getEnrichment(loaded);}else loadedHeat=loadedEnrichment=0;setChanged();var packet=ClientboundBlockEntityDataPacket.create(this);try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<62500)player.connection.send(packet);dispatchScope.commit();}}
    }
    public boolean hasItemLoaded(){return level!=null&&level.isClientSide?hasLoaded:!loaded.isEmpty();}public boolean isCraneLoading(){return progress!=1;}public boolean isAboveValidTarget(){return column() instanceof RbmkLoadable;}
    public boolean canTargetInteract(RbmkLoadable column){return column!=null&&(hasItemLoaded()?column.canLoad(loaded):column.canUnload());}
    public BlockPos columnPosition(){var dir=DummyableBlock.facing(getBlockState());var left=dir.getCounterClockWise();return new BlockPos(net.minecraft.util.Mth.floor(centerX-dir.getStepX()*posFront-left.getStepX()*posLeft+.5),centerY-1,net.minecraft.util.Mth.floor(centerZ-dir.getStepZ()*posFront-left.getStepZ()*posLeft+.5));}
    public RbmkColumnEntity column(){if(level==null)return null;var pos=columnPosition();if(!level.hasChunkAt(pos)||!(level.getBlockState(pos).getBlock() instanceof RbmkColumnBlock block))return null;return block.core(level,pos);}
    @Override public void setTarget(BlockPos pos){centerX=pos.getX();centerY=pos.getY()+RbmkDials.getColumnHeight(level)+1;centerZ=pos.getZ();var dir=DummyableBlock.facing(getBlockState()).getOpposite();spanF=findRoomExtent(pos,dir);dir=dir.getClockWise();spanR=findRoomExtent(pos,dir);dir=dir.getClockWise();spanB=findRoomExtent(pos,dir);dir=dir.getClockWise();spanL=findRoomExtent(pos,dir);height=7;setUpCrane=true;setChanged();}
    private int findRoomExtent(BlockPos center,Direction dir){for(int i=1;i<16;i++)if(!level.isEmptyBlock(new BlockPos(center.getX()+dir.getStepX()*i,centerY+6,center.getZ()+dir.getStepZ()*i)))return i-1;return 16;}
    public void cycleCraneRotation(){craneRotationOffset=(craneRotationOffset+90)%360;setChanged();}
    private void saveConfig(CompoundTag tag){tag.putBoolean("crane",setUpCrane);tag.putInt("craneRotationOffset",craneRotationOffset);tag.putInt("centerX",centerX);tag.putInt("centerY",centerY);tag.putInt("centerZ",centerZ);tag.putInt("spanF",spanF);tag.putInt("spanB",spanB);tag.putInt("spanL",spanL);tag.putInt("spanR",spanR);tag.putInt("height",height);tag.putDouble("posFront",posFront);tag.putDouble("posLeft",posLeft);tag.putBoolean("muffled",muffled);}
    private void loadConfig(CompoundTag tag){setUpCrane=tag.getBoolean("crane");craneRotationOffset=tag.getInt("craneRotationOffset");centerX=tag.getInt("centerX");centerY=tag.getInt("centerY");centerZ=tag.getInt("centerZ");spanF=tag.getInt("spanF");spanB=tag.getInt("spanB");spanL=tag.getInt("spanL");spanR=tag.getInt("spanR");height=tag.getInt("height");posFront=tag.getDouble("posFront");posLeft=tag.getDouble("posLeft");muffled=tag.getBoolean("muffled");}
    @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);saveConfig(tag);if(!loaded.isEmpty())tag.put("held",loaded.save(lookup));}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);loadConfig(tag);loaded=tag.contains("held")?ItemStack.parseOptional(lookup,tag.getCompound("held")):ItemStack.EMPTY;}
    @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putBoolean("crane",setUpCrane);tag.putBoolean("muffled",muffled);if(setUpCrane){saveConfig(tag);tag.putDouble("progress",progress);tag.putBoolean("hasLoaded",hasItemLoaded());tag.putDouble("loadedHeat",loadedHeat);tag.putDouble("loadedEnrichment",loadedEnrichment);}return tag;}
    @Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){setUpCrane=tag.getBoolean("crane");muffled=tag.getBoolean("muffled");if(setUpCrane){double front=posFront,left=posLeft;loadConfig(tag);syncFront=posFront;syncLeft=posLeft;posFront=front;posLeft=left;syncProgress=tag.getDouble("progress");hasLoaded=tag.getBoolean("hasLoaded");loadedHeat=tag.getDouble("loadedHeat");loadedEnrichment=tag.getDouble("loadedEnrichment");}}
    @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
    @Override public String computerType(){return "rbmk_crane";}@Override public String[] computerMethods(){return new String[]{"move","load","getRodInfo","getDepletion","getXenonPoison","getCranePos"};}
    @Override public Object[] callComputer(String method,ComputerArguments args)throws ComputerException{return switch(method){case "move"->{if(!setUpCrane)yield new Object[]{"Crane not found"};switch(args.checkString(0)){case "up"->{tiltFront=30;posFront+=SPEED;}case "down"->{tiltFront=-30;posFront-=SPEED;}case "left"->{tiltLeft=30;posLeft+=SPEED;}case "right"->{tiltLeft=-30;posLeft-=SPEED;}default->{}}setChanged();yield new Object[]{};}case "load"->{if(!setUpCrane)yield new Object[]{"Crane not found"};goesDown=true;yield new Object[]{};}case "getRodInfo"->{if(!(loaded.getItem() instanceof RbmkFuelRodItem))yield new Object[]{false,"No rod loaded"};var data=new LinkedHashMap<String,Object>();data.put("coreSkinTemp",RbmkFuelRodItem.getHullHeat(loaded));data.put("coreTemp",RbmkFuelRodItem.getCoreHeat(loaded));data.put("enrichment",RbmkFuelRodItem.getEnrichment(loaded));data.put("xenon",RbmkFuelRodItem.getPoison(loaded));data.put("rodName","item."+BuiltInRegistries.ITEM.getKey(loaded.getItem()).getPath());yield new Object[]{data};}case "getDepletion"->new Object[]{loaded.getItem() instanceof RbmkFuelRodItem?RbmkFuelRodItem.getEnrichment(loaded):"N/A"};case "getXenonPoison"->new Object[]{loaded.getItem() instanceof RbmkFuelRodItem?RbmkFuelRodItem.getPoison(loaded):"N/A"};case "getCranePos"->{var pos=columnPosition();yield new Object[]{pos.getX(),pos.getZ()};}default->throw new ComputerException("No such method: "+method);};}
    @Override public long energyStored(){return 0;}@Override public long energyCapacity(){return 0;}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("jade.hbm.rbmk.crane.lift",progress,1,0xc5c0a1));}
}
